  1→//! Workflow execution orchestration.
  2→
  3→use std::collections::{HashMap, HashSet};
  4→use std::path::Path;
  5→use std::time::{Duration, Instant};
  6→
  7→use tracing::warn;
  8→
  9→use crate::config::interpolation::InterpolationContext;
 10→use crate::config::schema::StepOverride;
 11→use crate::config::BivvyConfig;
 12→use crate::error::{BivvyError, Result};
 13→use crate::requirements::checker::GapChecker;
 14→use crate::requirements::installer;
 15→use crate::shell::OutputLine;
 16→use crate::steps::{
 17→    execute_step, run_check, ExecutionOptions, ResolvedStep, StepResult, StepStatus,
 18→};
 19→use crate::ui::spinner::live_output_callback;
 20→use crate::ui::theme::BivvyTheme;
 21→use crate::ui::{
 22→    format_duration, OutputMode, Prompt, PromptOption, PromptType, StatusKind, UserInterface,
 23→};
 24→
 25→use super::dependency::{DependencyGraph, SkipBehavior};
 26→use super::patterns::{self, StepContext};
 27→use super::recovery::{self, RecoveryAction};
 28→
 29→/// Maximum total execution attempts per step (auto-retries + manual retries).
 30→/// Prevents infinite loops when the recovery prompt always returns "retry"
 31→/// (e.g., in test environments with MockUI).
 32→const MAX_STEP_ATTEMPTS: u32 = 100;
 33→
 34→/// Progress events emitted during workflow execution.
 35→#[derive(Debug)]
 36→pub enum RunProgress<'a> {
 37→    /// A step is about to start.
 38→    StepStarting {
 39→        name: &'a str,
 40→        index: usize,
 41→        total: usize,
 42→    },
 43→    /// A step finished.
 44→    StepFinished {
 45→        name: &'a str,
 46→        result: &'a StepResult,
 47→    },
 48→    /// A step was skipped.
 49→    StepSkipped { name: &'a str },
 50→}
 51→
 52→/// Orchestrates the execution of a workflow.
 53→pub struct WorkflowRunner<'a> {
 54→    config: &'a BivvyConfig,
 55→    steps: HashMap<String, ResolvedStep>,
 56→}
 57→
 58→/// Result of running a workflow.
 59→#[derive(Debug)]
 60→pub struct WorkflowResult {
 61→    /// Workflow name.
 62→    pub workflow: String,
 63→    /// Results from each executed step.
 64→    pub steps: Vec<StepResult>,
 65→    /// Names of skipped steps.
 66→    pub skipped: Vec<String>,
 67→    /// Total duration.
 68→    pub duration: Duration,
 69→    /// Whether all steps succeeded.
 70→    pub success: bool,
 71→    /// Whether the workflow was aborted by the user during recovery.
 72→    pub aborted: bool,
 73→}
 74→
 75→/// Options for running a workflow.
 76→#[derive(Debug, Default)]
 77→pub struct RunOptions {
 78→    /// Workflow name (defaults to "default").
 79→    pub workflow: Option<String>,
 80→    /// Only run these steps.
 81→    pub only: HashSet<String>,
 82→    /// Skip these steps.
 83→    pub skip: HashSet<String>,
 84→    /// How to handle skipped step dependencies.
 85→    pub skip_behavior: SkipBehavior,
 86→    /// Force re-run these steps even if complete.
 87→    pub force: HashSet<String>,
 88→    /// Dry run mode.
 89→    pub dry_run: bool,
 90→    /// Requirements that are provided by the environment and should skip gap checks.
 91→    pub provided_requirements: HashSet<String>,
 92→    /// Active environment name for only_environments filtering.
 93→    pub active_environment: Option<String>,
 94→}
 95→
 96→impl<'a> WorkflowRunner<'a> {
 97→    /// Create a new workflow runner.
 98→    pub fn new(config: &'a BivvyConfig, steps: HashMap<String, ResolvedStep>) -> Self {
 99→        Self { config, steps }
100→    }
101→
102→    /// Run the specified workflow.
103→    pub fn run(
104→        &self,
105→        options: &RunOptions,
106→        context: &InterpolationContext,
107→        global_env: &HashMap<String, String>,
108→        project_root: &Path,
109→    ) -> Result<WorkflowResult> {
110→        self.run_with_progress(options, context, global_env, project_root, None, |_| {})
111→    }
112→
113→    /// Run the specified workflow with a progress callback.
114→    pub fn run_with_progress(
115→        &self,
116→        options: &RunOptions,
117→        context: &InterpolationContext,
118→        global_env: &HashMap<String, String>,
119→        project_root: &Path,
120→        mut gap_checker: Option<&mut GapChecker<'_>>,
121→        mut on_progress: impl FnMut(RunProgress<'_>),
122→    ) -> Result<WorkflowResult> {
123→        let start = Instant::now();
124→        let workflow_name = options.workflow.as_deref().unwrap_or("default");
125→
126→        // Build dependency graph
127→        let graph = self.build_graph(workflow_name)?;
128→
129→        // Compute skips
130→        let skipped = graph.compute_skips(&options.skip, options.skip_behavior);
131→
132→        // Get execution order
133→        let order = graph.topological_order()?;
134→
135→        // Filter by only_environments and --only/--skip
136→        let mut env_skipped: Vec<String> = Vec::new();
137→        let steps_to_run: Vec<_> = order
138→            .iter()
139→            .filter(|s| !skipped.contains(*s))
140→            .filter(|s| options.only.is_empty() || options.only.contains(*s))
141→            .filter(|s| {
142→                if let Some(step) = self.steps.get(*s) {
143→                    if !step.only_environments.is_empty() {
144→                        if let Some(ref active_env) = options.active_environment {
145→                            if !step.only_environments.iter().any(|e| e == active_env) {
146→                                env_skipped.push(s.to_string());
147→                                return false;
148→                            }
149→                        }
150→                    }
151→                }
152→                true
153→            })
154→            .cloned()
155→            .collect();
156→
157→        let total = steps_to_run.len();
158→
159→        // Report skipped steps
160→        for skip_name in &skipped {
161→            on_progress(RunProgress::StepSkipped { name: skip_name });
162→        }
163→        for skip_name in &env_skipped {
164→            on_progress(RunProgress::StepSkipped { name: skip_name });
165→        }
166→
167→        let mut results = Vec::new();
168→        let mut all_success = true;
169→        let mut failed_steps: HashSet<String> = HashSet::new();
170→
171→        for (index, step_name) in steps_to_run.iter().enumerate() {
172→            let step =
173→                self.steps
174→                    .get(step_name)
175→                    .ok_or_else(|| BivvyError::ConfigValidationError {
176→                        message: format!("Step '{}' not found in resolved steps", step_name),
177→                    })?;
178→
179→            // Check if any dependency failed
180→            if step.depends_on.iter().any(|dep| failed_steps.contains(dep)) {
181→                on_progress(RunProgress::StepSkipped { name: step_name });
182→                all_success = false;
183→                failed_steps.insert(step_name.clone());
184→                continue;
185→            }
186→
187→            // Check requirement gaps (non-UI: any blocking gap is an error)
188→            if let Some(ref mut checker) = gap_checker {
189→                let provided = if options.provided_requirements.is_empty() {
190→                    None
191→                } else {
192→                    Some(&options.provided_requirements)
193→                };
194→                let gaps = checker.check_step(step, provided);
195→                let blocking: Vec<_> = gaps
196→                    .iter()
197→                    .filter(|g| !g.status.is_satisfied() && !g.status.can_proceed())
198→                    .collect();
199→                if !blocking.is_empty() {
200→                    let names: Vec<_> = blocking.iter().map(|g| g.requirement.as_str()).collect();

200→                    let names: Vec<_> = blocking.iter().map(|g| g.requirement.as_str()).collect();
201→                    return Err(BivvyError::RequirementMissing {
202→                        requirement: names.join(", "),
203→                        message: format!(
204→                            "Step '{}' requires: {}. Run 'bivvy lint' for details.",
205→                            step_name,
206→                            names.join(", ")
207→                        ),
208→                    });
209→                }
210→            }
211→
212→            on_progress(RunProgress::StepStarting {
213→                name: step_name,
214→                index,
215→                total,
216→            });
217→
218→            let exec_options = ExecutionOptions {
219→                force: options.force.contains(step_name),
220→                dry_run: options.dry_run,
221→                capture_output: true,
222→                ..Default::default()
223→            };
224→
225→            let step_start = Instant::now();
226→            let result =
227→                match execute_step(step, project_root, context, global_env, &exec_options, None) {
228→                    Ok(result) => result,
229→                    Err(e) => {
230→                        warn!("Step '{}' errored: {}", step_name, e);
231→                        StepResult::failure(step_name, step_start.elapsed(), e.to_string(), None)
232→                    }
233→                };
234→
235→            on_progress(RunProgress::StepFinished {
236→                name: step_name,
237→                result: &result,
238→            });
239→
240→            let status = result.status();
241→
242→            results.push(result);
243→
244→            if status == StepStatus::Failed {
245→                all_success = false;
246→                if !step.allow_failure {
247→                    failed_steps.insert(step_name.clone());
248→                }
249→            }
250→        }
251→
252→        let mut all_skipped: Vec<String> = skipped.into_iter().collect();
253→        all_skipped.extend(env_skipped);
254→
255→        Ok(WorkflowResult {
256→            workflow: workflow_name.to_string(),
257→            steps: results,
258→            skipped: all_skipped,
259→            duration: start.elapsed(),
260→            success: all_success,
261→            aborted: false,
262→        })
263→    }
264→
265→    /// Run the specified workflow with direct UI interaction.
266→    ///
267→    /// Unlike `run_with_progress`, this method takes a `UserInterface` directly
268→    /// and handles interactive prompts for completed steps and sensitive steps.
269→    /// An optional `GapChecker` enables requirement gap detection before step execution.
270→    #[allow(clippy::too_many_arguments)]
271→    pub fn run_with_ui(
272→        &self,
273→        options: &RunOptions,
274→        context: &InterpolationContext,
275→        global_env: &HashMap<String, String>,
276→        project_root: &Path,
277→        workflow_non_interactive: bool,
278→        step_overrides: &HashMap<String, StepOverride>,
279→        mut gap_checker: Option<&mut GapChecker<'_>>,
280→        ui: &mut dyn UserInterface,
281→    ) -> Result<WorkflowResult> {
282→        let start = Instant::now();
283→        let workflow_name = options.workflow.as_deref().unwrap_or("default");
284→
285→        // Build dependency graph
286→        let graph = self.build_graph(workflow_name)?;
287→
288→        // Compute skips
289→        let skipped = graph.compute_skips(&options.skip, options.skip_behavior);
290→
291→        // Get execution order
292→        let order = graph.topological_order()?;
293→
294→        // Filter by only_environments
295→        let mut env_skipped: Vec<String> = Vec::new();
296→        let steps_to_run: Vec<_> = order
297→            .iter()
298→            .filter(|s| !skipped.contains(*s))
299→            .filter(|s| options.only.is_empty() || options.only.contains(*s))
300→            .filter(|s| {
301→                if let Some(step) = self.steps.get(*s) {
302→                    if !step.only_environments.is_empty() {
303→                        if let Some(ref active_env) = options.active_environment {
304→                            if !step.only_environments.iter().any(|e| e == active_env) {
305→                                env_skipped.push(s.to_string());
306→                                return false;
307→                            }
308→                        }
309→                    }
310→                }
311→                true
312→            })
313→            .cloned()
314→            .collect();
315→
316→        let total = steps_to_run.len();
317→        let theme = BivvyTheme::new();
318→
319→        // Report skipped steps (from --skip flag)
320→        for skip_name in &skipped {
321→            ui.message(&format!(
322→                "    {}",
323→                theme.format_skipped(&format!("{} skipped", skip_name))
324→            ));
325→        }
326→        for skip_name in &env_skipped {
327→            ui.message(&format!(
328→                "    {}",
329→                theme.format_skipped(&format!(
330→                    "{} skipped (not in {} environment)",
331→                    skip_name,
332→                    options.active_environment.as_deref().unwrap_or("unknown")
333→                ))
334→            ));
335→        }
336→
337→        let interactive = ui.is_interactive() && !workflow_non_interactive;
338→        let installer_ctx = installer::default_context();
339→
340→        let mut results = Vec::new();
341→        let mut all_success = true;
342→        let mut failed_steps: HashSet<String> = HashSet::new();
343→        let mut workflow_aborted = false;
344→
345→        for (index, step_name) in steps_to_run.iter().enumerate() {
346→            let step =
347→                self.steps
348→                    .get(step_name)
349→                    .ok_or_else(|| BivvyError::ConfigValidationError {
350→                        message: format!("Step '{}' not found in resolved steps", step_name),
351→                    })?;
352→
353→            // Blank line between steps
354→            if index > 0 {
355→                ui.message("");
356→            }
357→
358→            // Format step display with numbering: "[1/7] name — title" or "[1/7] name"
359→            let step_number = format!("[{}/{}]", index + 1, total);
360→            let step_display = if *step_name == step.title {
361→                format!(
362→                    "{} {}",
363→                    theme.step_number.apply_to(&step_number),
364→                    theme.step_title.apply_to(step_name)
365→                )
366→            } else {
367→                format!(
368→                    "{} {} {} {}",
369→                    theme.step_number.apply_to(&step_number),
370→                    theme.step_title.apply_to(step_name),
371→                    theme.dim.apply_to("—"),
372→                    theme.dim.apply_to(&step.title)
373→                )
374→            };
375→
376→            // Check if any dependency failed
377→            if step.depends_on.iter().any(|dep| failed_steps.contains(dep)) {
378→                ui.message(&step_display);
379→                ui.message(&format!(
380→                    "    {}",
381→                    StatusKind::Blocked.format(&theme, "Blocked (dependency failed)")
382→                ));
383→                ui.show_workflow_progress(index + 1, total, start.elapsed());
384→                all_success = false;
385→                failed_steps.insert(step_name.clone());
386→                continue;
387→            }
388→
389→            // Check requirement gaps before proceeding
390→            if let Some(ref mut checker) = gap_checker {
391→                let provided = if options.provided_requirements.is_empty() {
392→                    None
393→                } else {
394→                    Some(&options.provided_requirements)
395→                };
396→                let gaps = checker.check_step(step, provided);
397→                if !gaps.is_empty() {
398→                    let can_proceed =
399→                        installer::handle_gaps(&gaps, checker, ui, interactive, &installer_ctx)?;

400→                    if !can_proceed {
401→                        ui.message(&step_display);
402→                        ui.message(&format!(
403→                            "    {}",
404→                            StatusKind::Skipped.format(&theme, "Skipped (requirement not met)")
405→                        ));
406→                        ui.show_workflow_progress(index + 1, total, start.elapsed());
407→                        continue;
408→                    }
409→                }
410→            }
411→
412→            // Resolve effective prompt_if_complete (step-level, possibly overridden)
413→            let effective_prompt_if_complete = step_overrides
414→                .get(step_name)
415→                .and_then(|o| o.prompt_if_complete)
416→                .unwrap_or(step.prompt_if_complete);
417→
418→            let mut needs_force = options.force.contains(step_name);
419→            let mut already_prompted = false;
420→            let mut had_prompt = false;
421→
422→            // Check if already complete (unless forced)
423→            if !needs_force && !options.dry_run {
424→                if let Some(ref check) = step.completed_check {
425→                    let check_result = run_check(check, project_root);
426→                    if check_result.complete {
427→                        if interactive && effective_prompt_if_complete {
428→                            if step.skippable {
429→                                // Ask if they want to re-run (prompt IS the step header)
430→                                let prompt = Prompt {
431→                                    key: format!("rerun_{}", step_name),
432→                                    question: format!("Already complete. Re-run {}?", step_display),
433→                                    prompt_type: PromptType::Select {
434→                                        options: vec![
435→                                            PromptOption {
436→                                                label: "No (n)".to_string(),
437→                                                value: "no".to_string(),
438→                                            },
439→                                            PromptOption {
440→                                                label: "Yes (y)".to_string(),
441→                                                value: "yes".to_string(),
442→                                            },
443→                                        ],
444→                                    },
445→                                    default: Some("no".to_string()),
446→                                };
447→
448→                                let answer = ui.prompt(&prompt)?;
449→                                if answer.as_string() != "yes" {
450→                                    let reason = check_result.short_description();
451→                                    ui.message(&format!(
452→                                        "    {}",
453→                                        theme.format_skipped(&format!("Skipped ({})", reason))
454→                                    ));
455→                                    results.push(StepResult::skipped(&step.name, check_result));
456→                                    continue;
457→                                }
458→                                // User wants to re-run
459→                                needs_force = true;
460→                                already_prompted = true;
461→                                had_prompt = true;
462→                            } else {
463→                                // Not skippable, inform and re-run
464→                                ui.message(&step_display);
465→                                ui.message("    Re-running (not skippable)");
466→                                needs_force = true;
467→                            }
468→                        } else {
469→                            // Not interactive or prompt_if_complete is false: silently skip
470→                            ui.message(&step_display);
471→                            let reason = check_result.short_description();
472→                            ui.message(&format!(
473→                                "    {}",
474→                                theme.format_skipped(&format!("Skipped ({})", reason))
475→                            ));
476→                            results.push(StepResult::skipped(&step.name, check_result));
477→                            continue;
478→                        }
479→                    }
480→                }
481→            }
482→
483→            // In interactive mode, prompt before running skippable steps
484→            // (skip if already prompted by completed check)
485→            if interactive && step.skippable && !already_prompted {
486→                let prompt = Prompt {
487→                    key: format!("run_{}", step_name),
488→                    question: format!("{}?", step_display),
489→                    prompt_type: PromptType::Select {
490→                        options: vec![
491→                            PromptOption {
492→                                label: "Yes (y)".to_string(),
493→                                value: "yes".to_string(),
494→                            },
495→                            PromptOption {
496→                                label: "No (n)".to_string(),
497→                                value: "no".to_string(),
498→                            },
499→                        ],
500→                    },
501→                    default: Some("yes".to_string()),
502→                };
503→                let answer = ui.prompt(&prompt)?;
504→                if answer.as_string() != "yes" {
505→                    ui.message(&format!("    {}", theme.format_skipped("Skipped")));
506→                    results.push(StepResult::skipped(
507→                        &step.name,
508→                        crate::steps::CheckResult::complete("User declined"),
509→                    ));
510→                    continue;
511→                }
512→                had_prompt = true;
513→            }
514→
515→            // Show step name if no prompt was shown (non-interactive or non-skippable)
516→            if !had_prompt && !already_prompted {
517→                ui.message(&step_display);
518→            }
519→
520→            // Sensitive confirmation
521→            if step.sensitive && interactive {
522→                let prompt = Prompt {
523→                    key: format!("sensitive_{}", step_name),
524→                    question: "Handles sensitive data. Continue?".to_string(),
525→                    prompt_type: PromptType::Select {
526→                        options: vec![
527→                            PromptOption {
528→                                label: "Yes (y)".to_string(),
529→                                value: "yes".to_string(),
530→                            },
531→                            PromptOption {
532→                                label: "No (n)".to_string(),
533→                                value: "no".to_string(),
534→                            },
535→                        ],
536→                    },
537→                    default: Some("yes".to_string()),
538→                };
539→
540→                let answer = ui.prompt(&prompt)?;
541→                if answer.as_string() != "yes" {
542→                    if step.skippable {
543→                        ui.message(&format!(
544→                            "    {}",
545→                            theme.format_skipped("Skipped (declined sensitive step)")
546→                        ));
547→                        results.push(StepResult::skipped(
548→                            &step.name,
549→                            crate::steps::CheckResult::complete("User declined sensitive step"),
550→                        ));
551→                        continue;
552→                    } else {
553→                        return Err(BivvyError::StepExecutionError {
554→                            step: step_name.clone(),
555→                            message: format!(
556→                                "Step '{}' is sensitive and not skippable, but user declined",
557→                                step.title
558→                            ),
559→                        });
560→                    }
561→                }
562→                had_prompt = true;
563→            }
564→
565→            // Blank line before spinner when a prompt was shown (visual spacing)
566→            if had_prompt {
567→                ui.message("");
568→            }
569→
570→            // Build step context for pattern matching
571→            let step_ctx = StepContext {
572→                name: step_name,
573→                command: &step.command,
574→                requires: &step.requires,
575→                template: None,
576→            };
577→
578→            let mut retry_count: u32 = 0;
579→            let mut skipped_by_user = false;
580→            #[allow(unused_assignments)]
581→            let mut final_result: Option<StepResult> = None;
582→
583→            // Outer loop: step execution (retry/fix re-enter here)
584→            'step_execution: loop {
585→                // Fresh spinner per attempt
586→                let attempt_label = if retry_count > 0 {
587→                    format!(
588→                        "Running `{}`... (attempt {}/{})",
589→                        step.command,
590→                        retry_count + 1,
591→                        step.retry + 1
592→                    )
593→                } else {
594→                    format!("Running `{}`...", step.command)
595→                };
596→                let mut spinner = ui.start_spinner_indented(&attempt_label, 4);
597→
598→                // Create live output callback:
599→                // - Interactive mode: spinner-based ring buffer (3 lines verbose, 2 normal)

600→                // - Non-interactive verbose: print all output directly to stdout
601→                let output_mode = ui.output_mode();
602→                let output_callback = spinner
603→                    .progress_bar()
604→                    .and_then(|bar| {
605→                        let max_lines = match output_mode {
606→                            OutputMode::Verbose => 3,
607→                            OutputMode::Normal => 2,
608→                            _ => return None,
609→                        };
610→                        Some(live_output_callback(
611→                            bar,
612→                            attempt_label.clone(),
613→                            6,
614→                            max_lines,
615→                        ))
616→                    })
617→                    .or_else(|| {
618→                        // Non-interactive verbose: stream output directly
619→                        if output_mode == OutputMode::Verbose {
620→                            let cb: crate::shell::OutputCallback = Box::new(|line: OutputLine| {
621→                                let text = match &line {
622→                                    OutputLine::Stdout(s) => s.trim_end(),
623→                                    OutputLine::Stderr(s) => s.trim_end(),
624→                                };
625→                                if !text.is_empty() {
626→                                    println!("      {text}");
627→                                }
628→                            });
629→                            Some(cb)
630→                        } else {
631→                            None
632→                        }
633→                    });
634→
635→                let exec_options = ExecutionOptions {
636→                    force: needs_force,
637→                    dry_run: options.dry_run,
638→                    capture_output: output_callback.is_none(),
639→                    ..Default::default()
640→                };
641→
642→                let step_start = Instant::now();
643→                let result = match execute_step(
644→                    step,
645→                    project_root,
646→                    context,
647→                    global_env,
648→                    &exec_options,
649→                    output_callback,
650→                ) {
651→                    Ok(result) => result,
652→                    Err(e) => {
653→                        warn!("Step '{}' errored: {}", step_name, e);
654→                        StepResult::failure(step_name, step_start.elapsed(), e.to_string(), None)
655→                    }
656→                };
657→
658→                let duration_str = format_duration(result.duration);
659→
660→                match result.status() {
661→                    StepStatus::Completed => {
662→                        let detail = if retry_count > 0 {
663→                            Some(format!("succeeded on retry (attempt {})", retry_count + 1))
664→                        } else {
665→                            None
666→                        };
667→                        spinner.finish_success(&format!("{} ({})", step_name, duration_str));
668→                        let mut r = result;
669→                        r.recovery_detail = detail;
670→                        final_result = Some(r);
671→                        break 'step_execution;
672→                    }
673→                    StepStatus::Skipped => {
674→                        spinner.finish_skipped("Skipped");
675→                        final_result = Some(result);
676→                        break 'step_execution;
677→                    }
678→                    StepStatus::Failed => {
679→                        spinner.finish_error(&format!("Failed ({})", duration_str));
680→
681→                        // Build combined error output for pattern matching and display
682→                        let mut output_parts = Vec::new();
683→                        if let Some(ref err) = result.error {
684→                            output_parts.push(err.as_str());
685→                        }
686→                        if let Some(ref output) = result.output {
687→                            let trimmed = output.trim();
688→                            if !trimmed.is_empty() {
689→                                output_parts.push(trimmed);
690→                            }
691→                        }
692→                        let combined_output = output_parts.join("\n");
693→
694→                        // Match against pattern registry
695→                        let fix = patterns::find_fix(&combined_output, &step_ctx);
696→                        let hint = patterns::find_hint(&combined_output, &step_ctx);
697→
698→                        // Show error block — skip in non-interactive verbose
699→                        // where output was already streamed to stdout
700→                        let output_was_streamed =
701→                            !ui.is_interactive() && output_mode == OutputMode::Verbose;
702→                        if !output_was_streamed {
703→                            ui.show_error_block(&step.command, &combined_output, hint.as_deref());
704→                        }
705→
706→                        // allow_failure: record and move on, no recovery menu
707→                        if step.allow_failure {
708→                            final_result = Some(result);
709→                            break 'step_execution;
710→                        }
711→
712→                        // Auto-retry before showing recovery menu
713→                        if retry_count < step.retry {
714→                            retry_count += 1;
715→                            ui.message(&format!(
716→                                "    Retrying... (attempt {}/{})",
717→                                retry_count + 1,
718→                                step.retry + 1
719→                            ));
720→                            continue 'step_execution;
721→                        }
722→
723→                        // Non-interactive: no recovery menu
724→                        if !interactive {
725→                            final_result = Some(result);
726→                            break 'step_execution;
727→                        }
728→
729→                        // Safety: cap total attempts to prevent infinite loops
730→                        // (e.g., in tests where MockUI defaults to "retry")
731→                        if retry_count >= MAX_STEP_ATTEMPTS {
732→                            warn!(
733→                                "Step '{}' exceeded max recovery attempts ({})",
734→                                step_name, MAX_STEP_ATTEMPTS
735→                            );
736→                            final_result = Some(result);
737→                            break 'step_execution;
738→                        }
739→
740→                        // Interactive recovery menu
741→                        let has_hint = hint.is_some();
742→                        'recovery_menu: loop {
743→                            let action =
744→                                recovery::prompt_recovery(ui, step_name, fix.as_ref(), has_hint)?;
745→
746→                            match action {
747→                                RecoveryAction::Retry => {
748→                                    retry_count += 1;
749→                                    continue 'step_execution;
750→                                }
751→                                RecoveryAction::Fix(cmd) | RecoveryAction::CustomFix(cmd) => {
752→                                    if recovery::confirm_fix(ui, step_name, &cmd)? {
753→                                        let fix_ok =
754→                                            recovery::run_fix(&cmd, project_root, &step.env)?;
755→                                        if fix_ok {
756→                                            ui.message("    Fix command succeeded.");
757→                                        } else {
758→                                            ui.message("    Fix command failed.");
759→                                        }
760→                                        retry_count += 1;
761→                                        continue 'step_execution;
762→                                    } else {
763→                                        // User declined the fix — re-show recovery menu
764→                                        continue 'recovery_menu;
765→                                    }
766→                                }
767→                                RecoveryAction::Shell => {
768→                                    ui.message("    Dropping to debug shell (exit to return)...");
769→                                    crate::shell::debug::spawn_debug_shell(
770→                                        step_name,
771→                                        project_root,
772→                                        &step.env,
773→                                        global_env,
774→                                    )?;
775→                                    // After shell exit, re-show recovery menu
776→                                    continue 'recovery_menu;
777→                                }
778→                                RecoveryAction::Skip => {
779→                                    skipped_by_user = true;
780→                                    let mut r = result;
781→                                    r.recovery_detail =
782→                                        Some("skipped by user after failure".to_string());
783→                                    final_result = Some(r);
784→                                    break 'step_execution;
785→                                }
786→                                RecoveryAction::Abort => {
787→                                    workflow_aborted = true;
788→                                    let mut r = result;
789→                                    r.recovery_detail = Some("aborted by user".to_string());
790→                                    final_result = Some(r);
791→                                    break 'step_execution;
792→                                }
793→                            }
794→                        }
795→                    }
796→                    _ => {
797→                        final_result = Some(result);
798→                        break 'step_execution;
799→                    }

  1→//! Non-interactive UI for CI/headless environments.
  2→
  3→use std::collections::HashMap;
  4→use std::time::Duration;
  5→
  6→use crate::error::{BivvyError, Result};
  7→
  8→use super::progress::format_duration;
  9→use super::theme::BivvyTheme;
 10→use super::{
 11→    OutputMode, Prompt, PromptResult, PromptType, RunSummary, SpinnerHandle, StatusKind,
 12→    UserInterface,
 13→};
 14→
 15→/// UI implementation for non-interactive mode.
 16→///
 17→/// When running in CI (detected via `is_ci()`), the progress bar is
 18→/// suppressed since it produces noisy output in log-based environments.
 19→/// All other output (headers, summaries, errors) is preserved.
 20→pub struct NonInteractiveUI {
 21→    mode: OutputMode,
 22→    env_overrides: HashMap<String, String>,
 23→    is_ci: bool,
 24→}
 25→
 26→impl NonInteractiveUI {
 27→    /// Create a new non-interactive UI.
 28→    pub fn new(mode: OutputMode) -> Self {
 29→        // Collect BIVVY_PROMPT_* env vars
 30→        let env_overrides: HashMap<String, String> = std::env::vars()
 31→            .filter(|(k, _)| k.starts_with("BIVVY_PROMPT_"))
 32→            .collect();
 33→
 34→        Self {
 35→            mode,
 36→            env_overrides,
 37→            is_ci: crate::shell::is_ci(),
 38→        }
 39→    }
 40→
 41→    /// Create with explicit overrides (for testing).
 42→    pub fn with_overrides(mode: OutputMode, overrides: HashMap<String, String>) -> Self {
 43→        Self {
 44→            mode,
 45→            env_overrides: overrides,
 46→            is_ci: false,
 47→        }
 48→    }
 49→
 50→    /// Create with explicit CI flag (for testing).
 51→    pub fn with_ci(mode: OutputMode, is_ci: bool) -> Self {
 52→        let env_overrides: HashMap<String, String> = std::env::vars()
 53→            .filter(|(k, _)| k.starts_with("BIVVY_PROMPT_"))
 54→            .collect();
 55→
 56→        Self {
 57→            mode,
 58→            env_overrides,
 59→            is_ci,
 60→        }
 61→    }
 62→}
 63→
 64→impl UserInterface for NonInteractiveUI {
 65→    fn output_mode(&self) -> OutputMode {
 66→        self.mode
 67→    }
 68→
 69→    fn message(&mut self, msg: &str) {
 70→        if self.mode.shows_status() {
 71→            println!("{}", msg);
 72→        }
 73→    }
 74→
 75→    fn success(&mut self, msg: &str) {
 76→        if self.mode.shows_status() {
 77→            println!("✓ {}", msg);
 78→        }
 79→    }
 80→
 81→    fn warning(&mut self, msg: &str) {
 82→        if self.mode.shows_status() {
 83→            eprintln!("⚠ {}", msg);
 84→        }
 85→    }
 86→
 87→    fn error(&mut self, msg: &str) {
 88→        eprintln!("✗ {}", msg);
 89→    }
 90→
 91→    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
 92→        let is_multiselect = matches!(prompt.prompt_type, PromptType::MultiSelect { .. });
 93→
 94→        // Check environment override
 95→        let env_key = format!("BIVVY_PROMPT_{}", prompt.key.to_uppercase());
 96→        if let Some(value) = self.env_overrides.get(&env_key) {
 97→            if is_multiselect {
 98→                let values: Vec<String> = value.split(',').map(|s| s.trim().to_string()).collect();
 99→                return Ok(PromptResult::Strings(values));
100→            }
101→            return Ok(PromptResult::String(value.clone()));
102→        }
103→
104→        // Use default
105→        if let Some(default) = &prompt.default {
106→            if is_multiselect {
107→                let values: Vec<String> =
108→                    default.split(',').map(|s| s.trim().to_string()).collect();
109→                return Ok(PromptResult::Strings(values));
110→            }
111→            return Ok(PromptResult::String(default.clone()));
112→        }
113→
114→        Err(BivvyError::ConfigValidationError {
115→            message: format!(
116→                "Cannot prompt for '{}' in non-interactive mode (no default value)",
117→                prompt.key
118→            ),
119→        })
120→    }
121→
122→    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle> {
123→        if self.mode.shows_spinners() {
124→            println!("  {}", message);
125→        }
126→        Box::new(NoopSpinner { indent: 0 })
127→    }
128→
129→    fn start_spinner_indented(&mut self, message: &str, indent: usize) -> Box<dyn SpinnerHandle> {
130→        if self.mode.shows_spinners() {
131→            let prefix = " ".repeat(indent);
132→            println!("{}{}", prefix, message);
133→        }
134→        Box::new(NoopSpinner { indent })
135→    }
136→
137→    fn show_header(&mut self, title: &str) {
138→        if self.mode.shows_status() {
139→            println!("\n{}\n", title);
140→        }
141→    }
142→
143→    fn show_progress(&mut self, current: usize, total: usize) {
144→        if self.mode.shows_status() {
145→            println!("[{}/{}]", current, total);
146→        }
147→    }
148→
149→    fn show_run_header(
150→        &mut self,
151→        app_name: &str,
152→        workflow: &str,
153→        step_count: usize,
154→        version: &str,
155→    ) {
156→        if self.mode.shows_status() {
157→            let step_label = if step_count == 1 { "step" } else { "steps" };
158→            println!(
159→                "\n⛺ {} v{} · {} workflow · {} {}\n",
160→                app_name, version, workflow, step_count, step_label
161→            );
162→        }
163→    }
164→
165→    fn show_workflow_progress(&mut self, current: usize, total: usize, elapsed: Duration) {
166→        if self.is_ci {
167→            return;
168→        }
169→        if self.mode.shows_status() {
170→            let filled = if total > 0 { (current * 16) / total } else { 0 };
171→            let empty = 16 - filled;
172→            let bar = format!("{}{}", "█".repeat(filled), "░".repeat(empty));
173→            println!(
174→                "  [{}] {}/{} steps · {} elapsed",
175→                bar,
176→                current,
177→                total,
178→                format_duration(elapsed),
179→            );
180→        }
181→    }
182→
183→    fn show_hint(&mut self, hint: &str) {
184→        if self.mode.shows_status() {
185→            println!("  💡 {}", hint);
186→        }
187→    }
188→
189→    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>) {
190→        eprintln!();
191→        eprintln!("    ┌─ Command ──────────────────────────");
192→        eprintln!("    │ {}", command);
193→        if !output.is_empty() {
194→            eprintln!("    ├─ Output ───────────────────────────");
195→            for line in output.lines() {
196→                eprintln!("    │ {}", line);
197→            }
198→        }
199→        eprintln!("    └────────────────────────────────────");
200→        if let Some(h) = hint {
201→            eprintln!();
202→            eprintln!("    Hint: {}", h);
203→        }
204→    }
205→
206→    fn show_run_summary(&mut self, summary: &RunSummary) {
207→        if !self.mode.shows_status() {
208→            return;
209→        }
210→
211→        println!();
212→        println!("  ┌─ Summary ──────────────────────────");
213→
214→        for step in &summary.step_results {
215→            let icon = step.status.icon();
216→            let duration_str = step.duration.map(format_duration).unwrap_or_default();
217→            let detail_str = step.detail.as_deref().unwrap_or("");
218→
219→            let right_side = if !duration_str.is_empty() {
220→                duration_str
221→            } else if !detail_str.is_empty() {
222→                detail_str.to_string()
223→            } else {
224→                String::new()
225→            };
226→
227→            println!("  │ {} {:<20} {}", icon, step.name, right_side);
228→        }
229→
230→        println!("  ├────────────────────────────────────");
231→        println!(
232→            "  │ Total: {} · {} run · {} skipped",
233→            format_duration(summary.total_duration),
234→            summary.steps_run,
235→            summary.steps_skipped,
236→        );
237→        println!("  └────────────────────────────────────");
238→
239→        if summary.success {
240→            println!("  ✓ Setup complete!");
241→        } else {
242→            let status = StatusKind::Failed;
243→            eprintln!(
244→                "  {} Setup failed: {}",
245→                status.icon(),
246→                summary.failed_steps.join(", ")
247→            );
248→        }
249→    }
250→
251→    fn is_interactive(&self) -> bool {
252→        false
253→    }
254→
255→    fn set_output_mode(&mut self, mode: OutputMode) {
256→        self.mode = mode;
257→    }
258→}
