  6→/// Output verbosity mode.
  7→#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
  8→pub enum OutputMode {
  9→    /// Show all output including command output.
 10→    Verbose,
 11→    /// Show progress and status only.
 12→    #[default]
 13→    Normal,
 14→    /// Show minimal output (spinners + final status).
 15→    Quiet,
 16→    /// Show nothing except errors.
 17→    Silent,
 18→}
 19→
 20→impl FromStr for OutputMode {
 21→    type Err = String;
 22→
 23→    fn from_str(s: &str) -> Result<Self, Self::Err> {
 24→        match s.to_lowercase().as_str() {
 25→            "verbose" => Ok(Self::Verbose),
 26→            "normal" => Ok(Self::Normal),
 27→            "quiet" => Ok(Self::Quiet),
 28→            "silent" => Ok(Self::Silent),
 29→            _ => Err(format!("unknown output mode: {}", s)),
 30→        }
 31→    }
 32→}
 33→
 34→impl From<crate::config::schema::OutputMode> for OutputMode {
 35→    fn from(config_mode: crate::config::schema::OutputMode) -> Self {
 36→        match config_mode {
 37→            crate::config::schema::OutputMode::Verbose => Self::Verbose,
 38→            crate::config::schema::OutputMode::Quiet => Self::Quiet,
 39→            crate::config::schema::OutputMode::Silent => Self::Silent,
 40→        }
 41→    }
 42→}
 43→
 44→impl OutputMode {
 45→    /// Check if this mode shows command output.
 46→    pub fn shows_command_output(&self) -> bool {
 47→        matches!(self, Self::Verbose)
 48→    }
 49→
 50→    /// Check if this mode shows progress spinners.
 51→    pub fn shows_spinners(&self) -> bool {
 52→        matches!(self, Self::Verbose | Self::Normal | Self::Quiet)
 53→    }
 54→
 55→    /// Check if this mode shows status messages.
 56→    pub fn shows_status(&self) -> bool {
 57→        !matches!(self, Self::Silent)
 58→    }
 59→}
 60→
 61→/// Output writer that respects output mode.
 62→#[derive(Debug)]
 63→pub struct Output {
 64→    mode: OutputMode,
 65→}
 66→
 67→impl Output {
 68→    /// Create a new output writer.
 69→    pub fn new(mode: OutputMode) -> Self {
 70→        Self { mode }
 71→    }
 72→
 73→    /// Get the output mode.
 74→    pub fn mode(&self) -> OutputMode {
 75→        self.mode
 76→    }
 77→
 78→    /// Write a line if the mode allows status messages.
 79→    pub fn println(&self, msg: &str) {
 80→        if self.mode.shows_status() {
 81→            println!("{}", msg);
 82→        }
 83→    }
 84→
 85→    /// Write command output if verbose mode.
 86→    pub fn command_output(&self, output: &str) {
 87→        if self.mode.shows_command_output() {
 88→            print!("{}", output);
 89→            let _ = std::io::stdout().flush();
 90→        }
 91→    }
 92→}
