        ui.set_prompt_response("confirm_key", "false");

        let prompt = Prompt {
            key: "confirm_key".to_string(),
            question: "Continue?".to_string(),
            prompt_type: PromptType::Confirm,
            default: None,
        };

        let result = ui.prompt(&prompt).unwrap();
        assert_eq!(result.as_bool(), Some(false));
    }

