    #[test]
    fn mock_ui_confirm_without_response_or_default_returns_false() {
        let mut ui = MockUI::new();

        let prompt = Prompt {
            key: "confirm_key".to_string(),
            question: "Continue?".to_string(),
            prompt_type: PromptType::Confirm,
