    #[test]
    fn mock_ui_captures_run_headers() {
        let mut ui = MockUI::new();

        ui.show_run_header("MyApp", "default", 7, "1.0.0");

        assert_eq!(ui.run_headers().len(), 1);
        assert_eq!(
